pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock oracle that returns a fixed price
        address mockOracle = address(new MockOracle());
        // Construct payoff definition: transform price by +1
        // encoded as PayoffDefinition with type PAYOFF_LINEAR (0) direction LONG (0) and data = 1e18
        bytes memory payoffData = abi.encodePacked(int256(1e18));
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinitionLib.toPayoffDefinition(0, 0, bytes30(bytes32(payoffData))),
            oracle: IOracleProvider(mockOracle),
            maintenance: UFixed18Lib.from(1000e18),
            fundingFee: UFixed18.ZERO,
            makerFee: UFixed18.ZERO,
            takerFee: UFixed18.ZERO,
            positionFee: UFixed18.ZERO,
            makerLimit: UFixed18Lib.from(10000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(1e18)
            })
        });
        // Initialize product (msg.sender is address(this))
        c.initialize(info);
        // Call atVersion(1) - oracle returns price 5, but payoff transform adds 1 => reference returns 6, bug returns 5
        IOracleProvider.OracleVersion memory version = c.atVersion(1);
        // Expected price: oracle price 5 + 1 = 6
        assertTrue(Fixed18.unwrap(version.price) == 6e18, "Price should be transformed to 6");
    }
}

contract MockOracle {
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: block.timestamp, price: Fixed18.wrap(5e18)});
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: block.timestamp, price: Fixed18.wrap(5e18)});
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: block.timestamp, price: Fixed18.wrap(5e18)});
    }
}

library PayoffDefinitionLib {
    enum PayoffType { NONE, LINEAR, DECAYING_LINEAR } // example
    enum PayoffDirection { LONG, SHORT }
    function toPayoffDefinition(uint8 payoffType, uint8 direction, bytes30 data) internal pure returns (PayoffDefinition memory) {
        return PayoffDefinition({
            payoffType: PayoffType(payoffType),
            payoffDirection: PayoffDirection(direction),
            data: data
        });
    }
}

library UFixed18Lib {
    uint256 constant BASE = 1e18;
    UFixed18 constant ZERO = UFixed18.wrap(0);
    function from(uint256 a) internal pure returns (UFixed18) {
        return UFixed18.wrap(a * BASE);
    }
}

library Fixed18Lib {
    Fixed18 constant ZERO = Fixed18.wrap(0);
}

library Math {}
library SignedMath {}
library Address { function isContract(address account) internal view returns (bool) { return account.code.length > 0; } }
library UFixed18Lib { uint256 constant BASE = 1e18; UFixed18 constant ZERO = UFixed18.wrap(0); }
library Fixed18Lib { Fixed18 constant ZERO = Fixed18.wrap(0); }

