        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.payoffDefinition = C.PayoffDefinition(C.PayoffDefinitionLib.PayoffType.PAYOFF, C.PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0));
        info.oracle = IOracleProvider(address(0xdead)); // Invalid oracle address to trigger isContract check
        info.maintenance = UFixed18.wrap(1000000000000000000);
        info.fundingFee = UFixed18.wrap(100000000000000000);
        info.makerFee = UFixed18.wrap(100000000000000000);
        info.takerFee = UFixed18.wrap(100000000000000000);
        info.positionFee = UFixed18.wrap(100000000000000000);
        info.makerLimit = UFixed18.wrap(100000000000000000000);
        // Dummy curve
        C.JumpRateUtilizationCurve memory curve;
        curve.minRate = C.PackedFixed18.wrap(0);
        curve.maxRate = C.PackedFixed18.wrap(1000000000000000000);
        curve.targetRate = C.PackedFixed18.wrap(500000000000000000);
        curve.targetUtilization = C.PackedUFixed18.wrap(500000000000000000);
        info.utilizationCurve = curve;

        // Attempt to initialize; this will revert if controller() returns address(0)
        bool initFailed;
        try c.initialize(info) {
            initFailed = false;
        } catch {
            initFailed = true;
        }

        if (initFailed) {
            // Mutant fails; reference would not. Assert on the revert flag.
            assertTrue(initFailed);
        } else {
            // Reference: call atVersion(0) succeeds
            (bool ok, ) = address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", 0));
            assertTrue(ok);
        }
    }
}

